-- Source-backed universal US/Canada MVP content pack.
-- Generated by scripts/generate-mvp-migration.mjs from content/mvp/*.json.
-- Requires the local migration chain through 20260729020000.
-- Intentionally does not insert, update, delete, or publish treatment_media.

begin;

alter table public.treatments
  add column if not exists canada_status text;

alter table public.regional_price_estimates
  add column if not exists limitations text;

-- Preserve existing treatment IDs by upserting on the stable slug.
with payload as (
  select *
  from jsonb_to_recordset($treatments$[{"name":"Botox Cosmetic","slug":"botox","entity_type":"product","parent_slug":"neuromodulator","manufacturer":"Allergan Aesthetics, an AbbVie company","category":"Injectable","treatment_class":"Botulinum toxin type A neuromodulator","generic_name":"onabotulinumtoxinA","brand_name":"Botox Cosmetic","summary":"A prescription botulinum toxin type A injection that temporarily reduces selected expression lines by weakening targeted muscle activity.","primary_purpose":"Temporary improvement of specified dynamic facial and neck lines in adults; approved US cosmetic areas are product-label specific.","mechanism":"Binds to motor nerve terminals and inhibits acetylcholine release by cleaving SNAP-25, producing temporary chemodenervation of injected muscles.","intended_areas":["glabella","forehead","lateral canthal lines","platysma bands"],"what_it_changes":"Movement-driven lines and the pull of specifically injected muscles.","what_it_does_not_change":"It does not add tissue volume, replace structural support, fill a hollow, or resurface skin.","adds_volume":"No","tightening_level":"None; any contour change comes from altered muscle pull, not tissue tightening.","result_timing":"An effect can begin within 1 to 2 days and commonly strengthens during the first week.","sessions_text":"One treatment visit; repeat treatment is considered after the effect wanes and should follow the product label.","appointment_time":null,"downtime_text":"No required recovery period is specified in the label, although injection-site effects can occur.","swelling_text":"Localized swelling is possible.","bruising_text":"Injection-site bruising is possible.","exercise_restrictions":null,"longevity_text":"The FDA label describes approximately 3 to 4 months for glabellar-line effect; individual areas and patients vary.","pain_level":null,"reversibility":"Not immediately reversible; the effect usually diminishes as neuromuscular function recovers.","major_risks":"Unwanted weakness such as eyelid or brow ptosis, asymmetry, headache, hypersensitivity, and rare distant spread of toxin effect with swallowing or breathing difficulty. Contraindicated with hypersensitivity to a botulinum toxin preparation or infection at the injection site.","most_likely_disappointment":"Static etched lines or volume loss can remain even when muscle movement is reduced.","marketing_misconception":"Botox is not a dermal filler and its potency units cannot be converted directly to another botulinum toxin product.","provider_variables":"Muscle assessment, injection sites, dose, depth, symmetry planning, and management of adjacent-muscle spread.","skin_tone_notes":null,"pricing_basis":"Usually priced per Botox Cosmetic unit or, less transparently, by treatment area; Botox units must not be converted to Dysport units.","expected_result_magnitude":"Targeted, temporary reduction in selected expression lines; it is not a structural facial-volume treatment.","true_substitute_notes":"Botox and Dysport share a treatment class but have different labels and non-interchangeable potency units. Botox and fillers are different approaches.","when_not_appropriate":"Do not use with product hypersensitivity or infection at the proposed injection site; additional warnings and patient-specific exclusions require prescriber review.","fda_status":"FDA-approved prescription biologic for temporary improvement of moderate to severe glabellar lines, lateral canthal lines, forehead lines, and platysma bands in adults under the current US label.","canada_status":"Health Canada Drug Product Database lists Botox Cosmetic DIN 02531445 as approved; Canadian indications and dosing must follow the current Canadian product monograph.","evidence_grade":"High for product identity, mechanism, labelled indications, contraindications, and labelled duration; outcomes remain dose-, area-, and patient-dependent.","at_a_glance":{"onset":"Begins in days; builds during week 1","duration":"About 3–4 months for labelled glabellar treatment","downtime":"No required recovery; injection effects possible","reversibility":"Not immediately reversible"},"sort_rank":110,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"Dysport","slug":"dysport","entity_type":"product","parent_slug":"neuromodulator","manufacturer":"Ipsen Biopharmaceuticals; marketed in US aesthetics by Galderma","category":"Injectable","treatment_class":"Botulinum toxin type A neuromodulator","generic_name":"abobotulinumtoxinA","brand_name":"Dysport","summary":"A prescription botulinum toxin type A injection used to temporarily improve labelled glabellar lines by reducing targeted muscle activity.","primary_purpose":"Temporary improvement in the appearance of moderate to severe glabellar lines associated with procerus and corrugator muscle activity in adults younger than 65 under the US cosmetic label.","mechanism":"Acts at the neuromuscular junction to inhibit acetylcholine release and temporarily reduce activity in injected muscles.","intended_areas":["glabella"],"what_it_changes":"Movement-driven frown lines in the labelled glabellar treatment pattern.","what_it_does_not_change":"It does not add volume, replace structural support, or resurface skin.","adds_volume":"No","tightening_level":"None; it modifies muscle activity rather than tightening tissue.","result_timing":"Clinical cosmetic outcomes are assessed after treatment; visible change commonly develops over the first days to two weeks, but individual onset varies.","sessions_text":"One treatment visit; the US label states treatment should not occur more frequently than every three months.","appointment_time":null,"downtime_text":"No formal recovery period is specified, but injection-site reactions and unwanted weakness can occur.","swelling_text":"Localized swelling can occur after injection.","bruising_text":"Injection-site bruising can occur.","exercise_restrictions":null,"longevity_text":"Temporary; the US label limits retreatment frequency to no more often than every three months rather than promising an exact duration for every patient.","pain_level":null,"reversibility":"Not immediately reversible; effects generally diminish as neuromuscular function recovers.","major_risks":"Eyelid ptosis, headache, injection-site reactions, hypersensitivity including to cow's-milk protein, infection-site contraindication, and rare distant spread of toxin effect with swallowing or breathing difficulty.","most_likely_disappointment":"The US cosmetic indication is narrower than Botox Cosmetic's current label, and static lines or volume loss may persist.","marketing_misconception":"A Dysport unit is not equivalent to a Botox unit and no direct unit conversion should be presented.","provider_variables":"Label-appropriate patient selection, dose, injection pattern, anatomy, symmetry, and spread into adjacent muscles.","skin_tone_notes":null,"pricing_basis":"Usually priced per Dysport unit or by area; raw Dysport-unit prices must remain separate from Botox-unit prices.","expected_result_magnitude":"Temporary reduction of labelled glabellar-line severity, not facial volumization.","true_substitute_notes":"Same broad treatment class as Botox, but product potency units, labelling, dose, and clinical plan are not interchangeable.","when_not_appropriate":"Contraindicated with hypersensitivity to any botulinum toxin product or cow's-milk protein and with infection at the proposed site; prescriber review is required for other warnings.","fda_status":"FDA-approved prescription biologic for temporary improvement of moderate to severe glabellar lines associated with procerus and corrugator activity in adult patients younger than 65.","canada_status":"Health Canada Drug Product Database lists Dysport Aesthetic DIN 02387735 as marketed; use must follow the current Canadian product monograph.","evidence_grade":"High for product identity, labelled indication, dose-frequency limit, contraindications, and non-interchangeability; comparative onset or superiority claims are not established here.","at_a_glance":{"onset":"Develops over days; assess over roughly 2 weeks","duration":"Temporary; retreat no more often than every 3 months","downtime":"No formal recovery; injection effects possible","reversibility":"Not immediately reversible"},"sort_rank":120,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"Hyaluronic acid dermal fillers","slug":"ha-filler","entity_type":"class","parent_slug":null,"manufacturer":null,"category":"Injectable","treatment_class":"Hyaluronic acid dermal filler","generic_name":"cross-linked hyaluronic acid gel","brand_name":null,"summary":"A class of injectable gels that add or restore volume; each product is approved or licensed for specific tissues, depths, and treatment areas.","primary_purpose":"Product-specific correction or augmentation of approved facial or hand areas by adding gel volume.","mechanism":"An implanted hyaluronic acid gel occupies space in soft tissue; formulation, cross-linking, concentration, particle properties, and injection plane differ by product.","intended_areas":["lips","perioral lines","cheeks","chin","jawline","nasolabial folds","temples","infraorbital hollow","dorsal hands"],"what_it_changes":"Volume, contour, projection, and selected folds or hollows when an appropriately indicated product is placed in the intended tissue plane.","what_it_does_not_change":"It does not reduce muscle contraction like a neuromodulator and is not a skin-resurfacing treatment.","adds_volume":"Yes","tightening_level":"No direct tissue-tightening action; contour support can create a lifted appearance in selected anatomy.","result_timing":"Volume change is visible immediately, with assessment refined after early swelling settles.","sessions_text":"Often one visit with possible staged treatment or touch-up; amount and number of sessions depend on product, area, and goal.","appointment_time":null,"downtime_text":"Usually limited social downtime, but swelling, tenderness, redness, and bruising can be conspicuous for days and sometimes longer.","swelling_text":"Common and product/area dependent; lips can swell substantially.","bruising_text":"Common after injection.","exercise_restrictions":null,"longevity_text":"Product- and area-specific. FDA consumer guidance gives roughly 6 to 12 months for many absorbable HA fillers, while some approved products have longer study follow-up.","pain_level":null,"reversibility":"Many HA fillers can often be reduced with clinician-administered hyaluronidase, but this use is off-label in the US, response varies, and complete reversal is not guaranteed.","major_risks":"Swelling, bruising, pain, tenderness, lumps, infection, inflammatory reactions, and rare inadvertent intravascular injection causing tissue necrosis, vision loss, or stroke.","most_likely_disappointment":"The wrong product, amount, or placement can look overfilled, fail to address the actual cause, or require more than one syringe.","marketing_misconception":"Dermal fillers are not one interchangeable product and are structurally different from Botox.","provider_variables":"Diagnosis, product selection, injection plane, amount, cannula or needle choice, vascular safety technique, and complication readiness.","skin_tone_notes":"Filler is not selected by skin tone alone, but bruising, inflammation, and post-inflammatory pigment change may present differently; product labelling and injector experience still matter.","pricing_basis":"Usually priced per syringe or mL; price comparisons must retain product, syringe volume, area, and whether multiple syringes are expected.","expected_result_magnitude":"From subtle lip or line correction to structural contour change, depending on product and total volume.","true_substitute_notes":"HA fillers may be substitutes only when two specific products are intended for the same area and plane. They are a different approach from Botox.","when_not_appropriate":"Avoid when product contraindications apply, at infected or inflamed sites, or when the goal requires muscle relaxation, skin resurfacing, or surgery rather than volume.","fda_status":"The FDA approves dermal fillers product by product and for specific indications; the HA-filler class itself is not a single approved product.","canada_status":"Health Canada licenses HA filler devices product by product through MDALL for Class III devices; class-level status does not establish a licence for every brand or indication.","evidence_grade":"High for class mechanism, product-specific regulatory model, common reactions, and vascular risk; duration and suitability must remain product- and area-specific.","at_a_glance":{"onset":"Immediate volume; reassess after swelling","duration":"Product and area specific","downtime":"Swelling/bruising can last days","reversibility":"Often reducible with off-label hyaluronidase; not guaranteed"},"sort_rank":200,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"Juvéderm","slug":"juvederm","entity_type":"brand_family","parent_slug":"ha-filler","manufacturer":"Allergan Aesthetics, an AbbVie company","category":"Injectable","treatment_class":"Hyaluronic acid dermal filler family","generic_name":"cross-linked hyaluronic acid gels","brand_name":"Juvéderm Collection of Fillers","summary":"A family of hyaluronic acid fillers with product-specific formulations and approved treatment areas.","primary_purpose":"Product-specific facial augmentation or correction across cheeks, chin, temples, jawline, lips, perioral lines, folds, and infraorbital hollowing.","mechanism":"Cross-linked hyaluronic acid gel adds physical volume; rheology, concentration, cross-linking, lidocaine content, approved plane, and intended area differ by product.","intended_areas":["cheeks","chin","temples","jawline","lips","perioral lines","nasolabial folds","infraorbital hollow"],"what_it_changes":"Product-dependent volume, projection, contour, and selected folds or hollows.","what_it_does_not_change":"The family name does not identify one formulation, one indication, one duration, or a neuromodulator effect.","adds_volume":"Yes","tightening_level":"No direct tightening; contour support may look lifting in selected cases.","result_timing":"Immediate gel volume, followed by reassessment after injection-related swelling.","sessions_text":"Usually one visit per area with possible staged treatment or touch-up; product and volume are individualized.","appointment_time":null,"downtime_text":"Typically limited, but swelling, bruising, tenderness, redness, firmness, and lumps may occur.","swelling_text":"Common and area dependent.","bruising_text":"Common after injection.","exercise_restrictions":null,"longevity_text":"Varies by the specific Juvéderm product, treatment area, amount, and patient; family-wide duration claims are not used.","pain_level":null,"reversibility":"The HA gel may often be reduced with off-label hyaluronidase, but response is product dependent and not guaranteed.","major_risks":"Injection-site reactions, lumps or nodules, infection, inflammatory reactions, and rare intravascular injection with necrosis, vision loss, or stroke.","most_likely_disappointment":"Choosing by brand family rather than by the exact product and intended area can create an invalid comparison or mismatched outcome.","marketing_misconception":"Juvéderm is a portfolio, not a single filler with one set of indications or one longevity.","provider_variables":"Specific product, volume, injection plane, anatomy, technique, and management of vascular complications.","skin_tone_notes":null,"pricing_basis":"Usually per syringe or mL; the exact Juvéderm product and syringe volume must be retained.","expected_result_magnitude":"Product and treatment-plan dependent.","true_substitute_notes":"Juvéderm and Restylane are comparable brand families, but individual products are substitutes only where indications, area, plane, and desired properties overlap.","when_not_appropriate":"When no product in the family is appropriate for the intended area or when filler contraindications or a non-volume problem applies.","fda_status":"Juvéderm devices are FDA-approved through product-specific PMAs and supplements; the brand family does not have one universal indication.","canada_status":"Health Canada MDALL lists active Class III Juvéderm licences, including family and product-specific records; the exact licensed device and intended use must be checked.","evidence_grade":"High for family composition and product-specific regulatory status; family-wide outcome and duration claims are intentionally avoided.","at_a_glance":{"onset":"Immediate volume; reassess after swelling","duration":"Varies by product and area","downtime":"Swelling/bruising can last days","reversibility":"Often reducible with off-label hyaluronidase"},"sort_rank":210,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"Restylane","slug":"restylane","entity_type":"brand_family","parent_slug":"ha-filler","manufacturer":"Galderma / Q-Med AB","category":"Injectable","treatment_class":"Hyaluronic acid dermal filler family","generic_name":"cross-linked hyaluronic acid gels","brand_name":"Restylane","summary":"A family of hyaluronic acid fillers whose individual products have distinct formulations, properties, and approved treatment areas.","primary_purpose":"Product-specific augmentation or correction of lips, folds, cheeks, chin, temples, infraorbital hollowing, and dorsal hands.","mechanism":"Cross-linked hyaluronic acid gel adds physical volume; formulation technology, gel properties, lidocaine content, intended tissue plane, and area differ by product.","intended_areas":["lips","perioral lines","nasolabial folds","cheeks","chin","temples","infraorbital hollow","dorsal hands"],"what_it_changes":"Product-dependent volume, shape, projection, and correction of selected folds or hollows.","what_it_does_not_change":"The family is not one interchangeable formulation and does not relax muscles like a botulinum toxin.","adds_volume":"Yes","tightening_level":"No direct tissue tightening.","result_timing":"Immediate gel volume, with final assessment after early swelling settles.","sessions_text":"Usually one visit per area with possible staged treatment or touch-up.","appointment_time":null,"downtime_text":"Typically limited, but swelling, bruising, pain, tenderness, redness, and lumps can occur.","swelling_text":"Common and area dependent.","bruising_text":"Common after injection.","exercise_restrictions":null,"longevity_text":"Varies by exact Restylane product, area, amount, and patient; no family-wide duration is assigned.","pain_level":null,"reversibility":"The HA gel may often be reduced with off-label hyaluronidase, with product-dependent and incomplete response possible.","major_risks":"Injection-site reactions, nodules, infection, inflammatory reactions, and rare intravascular injection causing necrosis, vision loss, or stroke.","most_likely_disappointment":"A family-level comparison can hide clinically important product and treatment-area differences.","marketing_misconception":"Restylane is a portfolio, not a single filler.","provider_variables":"Specific product, total volume, anatomy, plane, needle or cannula, and complication preparedness.","skin_tone_notes":null,"pricing_basis":"Usually per syringe or mL; retain the exact product and syringe volume.","expected_result_magnitude":"Product and treatment-plan dependent.","true_substitute_notes":"Restylane and Juvéderm are comparable families, but individual products are true substitutes only where their intended areas, planes, and goals overlap.","when_not_appropriate":"When filler contraindications apply, the intended area lacks an appropriate product, or the concern is muscular, textural, or surgical rather than volumetric.","fda_status":"Restylane devices are FDA-approved through product-specific PMAs and supplements; each product retains its own indication.","canada_status":"Health Canada MDALL lists active Class III Restylane licences, including product-specific records such as Restylane Kysse; exact licensed intended use must be checked.","evidence_grade":"High for family composition, safety framework, and product-specific regulation; no family-wide superiority or duration claim is made.","at_a_glance":{"onset":"Immediate volume; reassess after swelling","duration":"Varies by product and area","downtime":"Swelling/bruising can last days","reversibility":"Often reducible with off-label hyaluronidase"},"sort_rank":220,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"Juvéderm Voluma XC","slug":"juvederm-voluma","entity_type":"product","parent_slug":"juvederm","manufacturer":"Allergan Aesthetics, an AbbVie company","category":"Injectable","treatment_class":"Hyaluronic acid dermal filler","generic_name":"cross-linked hyaluronic acid gel with lidocaine","brand_name":"Juvéderm Voluma XC","summary":"A hyaluronic acid filler formulated for deep structural augmentation in specific approved facial areas.","primary_purpose":"Deep augmentation for age-related midface volume deficit, chin-profile improvement, and temple hollowing in adults over 21 under the current US labelling.","mechanism":"A 20 mg/mL cross-linked hyaluronic acid gel with 0.3% lidocaine is implanted in product-specific deep tissue planes to add volume and contour.","intended_areas":["cheeks","chin","temples"],"what_it_changes":"Midface volume, cheek contour, chin projection, or temple hollowing when used in the corresponding labelled plane.","what_it_does_not_change":"It is not a lip-specific filler, does not relax facial muscles, and does not tighten skin directly.","adds_volume":"Yes","tightening_level":"No direct tightening; structural volume can change contour.","result_timing":"Volume change is immediate; touch-up assessment in pivotal studies occurred after early swelling, commonly at weeks rather than the same day.","sessions_text":"One initial treatment with possible touch-up according to the labelled area and study protocol.","appointment_time":null,"downtime_text":"Injection-site responses are common and may last days to weeks.","swelling_text":"Common; severity and duration vary by area and technique.","bruising_text":"Common after injection.","exercise_restrictions":"The patient labelling advises minimizing strenuous exercise and extensive sun or heat exposure for the first 24 hours or until initial swelling and redness resolve.","longevity_text":"Cheek clinical-study benefit was evaluated through up to 24 months; this is not a promise that every treatment or newly approved area lasts 24 months.","pain_level":null,"reversibility":"May often be reduced with off-label hyaluronidase, but complete or immediate reversal is not guaranteed.","major_risks":"Swelling, tenderness, firmness, lumps, bruising, redness, infection, inflammatory reactions, and rare intravascular injection with necrosis, visual impairment, or stroke.","most_likely_disappointment":"Using a structural cheek/chin/temple filler for a lip goal is an intended-area mismatch; one syringe may also be insufficient for bilateral structural correction.","marketing_misconception":"Voluma and Restylane Kysse are not like-for-like products merely because both are HA fillers.","provider_variables":"Area-specific plane, amount, facial proportions, injection technique, and vascular anatomy.","skin_tone_notes":"The US labelling reports study enrollment across Fitzpatrick skin types; this does not eliminate individual risk of bruising, inflammation, or pigment change.","pricing_basis":"Usually per 1 mL syringe; total cost depends on area and number of syringes.","expected_result_magnitude":"Structural, area-dependent contour change rather than fine surface-line smoothing.","true_substitute_notes":"Not a true substitute for Restylane Kysse because their labelled intended areas differ; the comparison is educational and area mismatch must remain visible.","when_not_appropriate":"Not appropriate for lip augmentation under this profile or when filler contraindications, infection, severe allergy history, or a non-volume concern applies.","fda_status":"FDA-approved by PMA supplements for cheek augmentation for age-related midface volume deficit, chin augmentation, and temple hollowing in adults over 21.","canada_status":"Health Canada MDALL lists Juvéderm Voluma with lidocaine under active Class III medical-device licence 77899.","evidence_grade":"High for formulation, labelled areas, contraindications, adverse events, and pivotal-study follow-up; individual durability and required volume vary.","at_a_glance":{"onset":"Immediate volume; reassess after swelling","duration":"Cheek study follow-up up to 24 months","downtime":"Swelling/bruising commonly lasts days","reversibility":"Often reducible with off-label hyaluronidase"},"sort_rank":230,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"Restylane Kysse","slug":"restylane-kysse","entity_type":"product","parent_slug":"restylane","manufacturer":"Galderma / Q-Med AB","category":"Injectable","treatment_class":"Hyaluronic acid dermal filler","generic_name":"cross-linked hyaluronic acid gel with lidocaine","brand_name":"Restylane Kysse","summary":"A flexible hyaluronic acid filler approved in the US for lip augmentation and upper perioral lines.","primary_purpose":"Add fullness to the lips and correct upper perioral rhytids in adults over 21.","mechanism":"Cross-linked hyaluronic acid gel with lidocaine is injected into lip or upper-perioral tissue to add temporary volume and smooth selected lines.","intended_areas":["lips","upper perioral lines"],"what_it_changes":"Lip fullness, definition, and selected upper-lip lines.","what_it_does_not_change":"It is not intended in this profile for cheek, chin, or temple structural augmentation and does not relax muscles.","adds_volume":"Yes","tightening_level":"None","result_timing":"Volume is visible immediately; assessment should allow early lip swelling to settle.","sessions_text":"One initial treatment with optional touch-up as clinically appropriate.","appointment_time":null,"downtime_text":"Lip-site reactions are very common; swelling, tenderness, bruising, lumps, and firmness may remain visible for days and sometimes longer.","swelling_text":"Very common after lip injection; most trial diary symptoms resolved within about two weeks.","bruising_text":"Common after lip injection.","exercise_restrictions":null,"longevity_text":"In the FDA pivotal study, 60% of subjects were responders at week 48; this does not guarantee one-year correction for every patient.","pain_level":null,"reversibility":"May often be reduced with off-label hyaluronidase, but response is variable and complete reversal is not guaranteed.","major_risks":"Swelling, bruising, tenderness, pain, lumps, infection, inflammatory reactions, and rare intravascular injection with necrosis, vision impairment, or stroke.","most_likely_disappointment":"Swelling can temporarily exaggerate the result, and the product is not designed to replace structural cheek or chin augmentation.","marketing_misconception":"A one-year study responder rate is not the same as a guaranteed one-year result.","provider_variables":"Lip anatomy, amount, symmetry, injection plane, technique, and management of vascular compromise.","skin_tone_notes":"The pivotal study included a Fitzpatrick-skin-type subgroup analysis; individual bruising and pigment response can still vary.","pricing_basis":"Usually per 1 mL syringe; half-syringe or promotional pricing must remain separate.","expected_result_magnitude":"Localized lip and upper-perioral correction.","true_substitute_notes":"Not a true substitute for Voluma because the products have different labelled intended areas and structural goals.","when_not_appropriate":"Not appropriate for the Voluma-profile cheek, chin, or temple goals; avoid when label contraindications or active infection apply.","fda_status":"FDA-approved under PMA supplement P140029/S021 for lip augmentation and correction of upper perioral rhytids in patients over 21.","canada_status":"Health Canada MDALL lists Restylane Kysse under active Class III licence 95283.","evidence_grade":"High for formulation, labelled area, pivotal-study outcomes, and safety; long-term response remains individual.","at_a_glance":{"onset":"Immediate volume; reassess after swelling","duration":"60% pivotal-study responder rate at week 48","downtime":"Lip swelling/bruising can last days","reversibility":"Often reducible with off-label hyaluronidase"},"sort_rank":240,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"Sculptra","slug":"sculptra","entity_type":"product","parent_slug":"collagen-stimulator","manufacturer":"Galderma","category":"Injectable","treatment_class":"Poly-L-lactic acid collagen biostimulator","generic_name":"injectable poly-L-lactic acid (PLLA-SCA)","brand_name":"Sculptra","summary":"An injectable poly-L-lactic acid biostimulator used in a staged series for gradual correction of labelled facial wrinkles and folds.","primary_purpose":"Correction of shallow to deep nasolabial-fold contour deficiencies, fine lines and wrinkles in the cheek region, and other facial wrinkles in immunocompetent adults under the US aesthetic labelling.","mechanism":"PLLA microparticles produce a local tissue response associated with gradual collagen deposition; initial water-related fullness subsides before the treatment effect develops.","intended_areas":["cheek wrinkles","nasolabial folds","marionette lines","chin wrinkles"],"what_it_changes":"Gradual tissue support and correction of selected facial wrinkles or contour deficiencies.","what_it_does_not_change":"It does not provide the same predictable immediate gel contour as an HA filler and is not used in the lip vermilion or periorbital area under the IFU.","adds_volume":"Gradually, through biostimulation rather than a persistent HA gel bolus.","tightening_level":"No device-like tightening; gradual collagen response may improve support.","result_timing":"Most clinical-study participants saw results by about one month; improvement develops gradually.","sessions_text":"Average 2 to 3 sessions over several months; typical treatment is three sessions at least 3 to 4 weeks apart.","appointment_time":null,"downtime_text":"Injection-site swelling, tenderness, redness, pain, bruising, bleeding, itching, and lumps can occur.","swelling_text":"Common initially and can temporarily mimic correction before subsiding.","bruising_text":"Common after injection.","exercise_restrictions":null,"longevity_text":"The current manufacturer summary and cheek clinical program report sustained improvement for up to two years; individual response varies.","pain_level":null,"reversibility":"Not enzymatically reversible like an HA filler; effects and adverse nodules may be difficult to correct.","major_risks":"Injection reactions, papules or nodules including delayed inflammatory nodules, granuloma, infection, and intravascular injection with infarction or embolic phenomena.","most_likely_disappointment":"Early post-injection fullness fades, results are gradual, and a multi-session course may be required.","marketing_misconception":"Sculptra is not an immediately shapeable HA filler and 'collagen stimulation' does not make it risk-free or reversible.","provider_variables":"Reconstitution, hydration time, dilution, injection plane, distribution, session spacing, massage instruction, and avoiding overcorrection.","skin_tone_notes":null,"pricing_basis":"Usually per vial; compare the number of vials per session and the planned number of sessions.","expected_result_magnitude":"Gradual, diffuse correction rather than a sharply localized immediate contour.","true_substitute_notes":"Sculptra and Radiesse both have biostimulatory effects but differ in material, immediate volume, reversibility, technique, and labelled uses.","when_not_appropriate":"Contraindicated with ingredient hypersensitivity or a history of keloid formation or hypertrophic scarring; not for lip vermilion or periorbital injection under the IFU.","fda_status":"FDA-approved by PMA and supplements for specified facial contour deficiencies and wrinkles, including the 2023 cheek fine-line and wrinkle indication.","canada_status":"Health Canada MDALL lists Sculptra under active Class III licence 71658.","evidence_grade":"High for indication, treatment course, safety, and two-year cheek-study follow-up; aesthetic response and vial needs vary.","at_a_glance":{"onset":"Gradual; often visible by about 1 month","duration":"Study support up to 2 years","downtime":"Injection swelling/bruising; nodules can be delayed","reversibility":"Not enzymatically reversible"},"sort_rank":310,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"Radiesse","slug":"radiesse","entity_type":"product","parent_slug":"collagen-stimulator","manufacturer":"Merz Aesthetics","category":"Injectable","treatment_class":"Calcium hydroxylapatite dermal filler and biostimulator","generic_name":"calcium hydroxylapatite microspheres in an aqueous gel carrier","brand_name":"Radiesse / Radiesse (+)","summary":"An injectable calcium hydroxylapatite filler that provides immediate gel-carrier volume and a longer tissue response around resorbable microspheres.","primary_purpose":"Correction of moderate to severe facial wrinkles and folds, selected lower-face or jawline contour indications under current product labelling, and correction of dorsal-hand volume loss.","mechanism":"Calcium hydroxylapatite microspheres suspended in a gel carrier provide immediate fill; the carrier dissipates as tissue forms around the microspheres, which are gradually resorbed.","intended_areas":["nasolabial folds","lower face","jawline","dorsal hands"],"what_it_changes":"Immediate volume and structural contour in approved tissue planes, with a subsequent tissue response.","what_it_does_not_change":"It does not relax muscles and cannot be dissolved with hyaluronidase like an HA filler.","adds_volume":"Yes, immediately","tightening_level":"No device-like tightening; structural support and diluted off-label uses must not be conflated with labelled correction.","result_timing":"Immediate volume, followed by evolution as the carrier dissipates and tissue response develops.","sessions_text":"Often one treatment with individualized amount; additional treatment depends on area, response, and label.","appointment_time":null,"downtime_text":"Swelling, bruising, redness, pain, itching, and tenderness can occur; hand and facial recovery differ.","swelling_text":"Common after injection.","bruising_text":"Common after injection.","exercise_restrictions":null,"longevity_text":"FDA consumer guidance describes calcium hydroxylapatite filler effects as approximately 18 months; individual product, area, and patient results vary.","pain_level":null,"reversibility":"Not dissolvable with hyaluronidase; correction of unwanted placement can be difficult.","major_risks":"Injection reactions, nodules, infection, material visibility or palpability, and rare intravascular injection with necrosis, visual loss, or stroke.","most_likely_disappointment":"Immediate correction can evolve as the carrier dissipates, and unwanted product cannot be simply enzymatically dissolved.","marketing_misconception":"Radiesse is not interchangeable with Sculptra or HA filler; hyperdilute protocols may be off-label and should not redefine the approved product profile.","provider_variables":"Product version, dilution if any, plane, area, amount, anatomy, and complication management.","skin_tone_notes":null,"pricing_basis":"Usually per 1.5 mL syringe; retain syringe volume, product version, area, and any dilution protocol.","expected_result_magnitude":"Immediate structural correction with a subsequent tissue response.","true_substitute_notes":"Overlaps with Sculptra in some broad goals but differs in immediate volume, composition, injection plan, reversibility, and labelled indications.","when_not_appropriate":"When a reversible HA option is required, the desired area is not in the product labelling, or product contraindications or active infection apply.","fda_status":"FDA-approved by PMA and supplements for product-specific facial and hand indications; current Radiesse (+) labelling must be checked for the exact area.","canada_status":"Health Canada MDALL lists active Class III licences for Radiesse (78893) and Radiesse (+) (95140).","evidence_grade":"High for composition, approved-use framework, immediate filler action, and serious risks; off-label dilution outcomes are not generalized.","at_a_glance":{"onset":"Immediate volume","duration":"Approximately 18 months in FDA class guidance","downtime":"Injection swelling/bruising can last days","reversibility":"Not dissolvable with hyaluronidase"},"sort_rank":320,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"Thermage FLX","slug":"thermage","entity_type":"device","parent_slug":"energy-device","manufacturer":"Solta Medical","category":"Energy device","treatment_class":"Monopolar radiofrequency treatment","generic_name":"6.78 MHz monopolar radiofrequency system","brand_name":"Thermage FLX","summary":"A noninvasive monopolar radiofrequency platform that heats tissue while cooling the skin surface.","primary_purpose":"Noninvasive treatment of wrinkles and rhytids within the device's cleared indications; cosmetic 'lifting' language should be understood as modest tissue contraction/remodelling rather than surgery.","mechanism":"Delivers 6.78 MHz monopolar radiofrequency energy to produce controlled tissue heating and selective coagulation while contact cooling protects the epidermis.","intended_areas":["face","periorbital area","neck","body"],"what_it_changes":"May produce gradual, modest smoothing or tightening through thermal tissue contraction and remodelling.","what_it_does_not_change":"It does not add filler volume, paralyze muscles, remove large skin excess, or reproduce a surgical facelift.","adds_volume":"No","tightening_level":"Modest and variable; noninvasive.","result_timing":"Manufacturer materials describe gradual change over roughly 2 to 6 months.","sessions_text":"Commonly marketed as one treatment; repeat treatment is individualized and not guaranteed by clearance.","appointment_time":null,"downtime_text":"Usually no planned downtime, but transient redness, swelling, soreness, or contour symptoms can occur.","swelling_text":"Temporary swelling is possible.","bruising_text":"Not a typical treatment effect, but individual reactions vary.","exercise_restrictions":null,"longevity_text":"Manufacturer materials describe results lasting about 1 to 2 years; independent evidence is heterogeneous and individual response varies.","pain_level":null,"reversibility":"Not reversible; delivered thermal injury cannot be withdrawn.","major_risks":"Pain, erythema, swelling, burns, blisters, scarring, pigment change, altered sensation, nodules, and contour irregularity; electrical implants are an important contraindication in device instructions.","most_likely_disappointment":"Improvement can be subtle or absent and should not be compared with surgical lifting.","marketing_misconception":"FDA clearance for device indications is not proof of a facelift-equivalent result.","provider_variables":"Tip, pulse count, energy, treatment vectors, tissue contact, cooling, anatomy, and recognition of excessive heating.","skin_tone_notes":"Radiofrequency is not chromophore-targeted, but burns and post-inflammatory pigment change remain possible; settings and operator experience matter.","pricing_basis":"Usually per session, treatment area, and pulse/tip plan; face, eyes, neck, and body prices are not interchangeable.","expected_result_magnitude":"Subtle-to-moderate noninvasive change in selected patients.","true_substitute_notes":"Thermage FLX and Ultherapy are different energy modalities with overlapping broad goals, not identical treatments.","when_not_appropriate":"Not for someone expecting surgical correction; device instructions flag implanted electrical devices and require assessment of skin and medical contraindications.","fda_status":"Thermage FLX received FDA 510(k) clearance K170758 for device-specific noninvasive indications including treatment of wrinkles and rhytids; clearance is not an approval of every marketing claim.","canada_status":"Health Canada MDALL lists Thermage FLX under active Class III licence 112966; older Thermage CPT records also exist.","evidence_grade":"High for device identity and regulatory mechanism; moderate and heterogeneous for magnitude and durability of cosmetic tightening.","at_a_glance":{"onset":"Gradual over months","duration":"Manufacturer estimate about 1–2 years","downtime":"Usually none planned; thermal reactions possible","reversibility":"Not reversible"},"sort_rank":410,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"Ultherapy","slug":"ultherapy","entity_type":"device","parent_slug":"energy-device","manufacturer":"Merz Aesthetics / Ulthera, Inc.","category":"Energy device","treatment_class":"Microfocused ultrasound with visualization","generic_name":"microfocused ultrasound system with real-time imaging","brand_name":"Ultherapy","summary":"A noninvasive microfocused-ultrasound platform that images tissue and deposits focal thermal-coagulation points at selected depths.","primary_purpose":"Device-specific noninvasive lifting of brow and lax submental and neck tissue and improvement of décolletage lines under US clearances.","mechanism":"Real-time ultrasound imaging guides microfocused ultrasound energy to create discrete thermal-coagulation points at selected tissue depths, initiating a wound-healing and collagen-remodelling response.","intended_areas":["brow","submental area","neck","décolletage"],"what_it_changes":"May produce modest, gradual lifting or tightening in selected areas.","what_it_does_not_change":"It does not add volume, remove skin, relax muscles, or equal a surgical facelift.","adds_volume":"No","tightening_level":"Modest and variable; noninvasive.","result_timing":"Manufacturer and clinical literature describe change developing over about 2 to 3 months and continuing up to 6 months.","sessions_text":"Often one treatment in manufacturer protocols; additional treatment depends on response and clinical plan.","appointment_time":null,"downtime_text":"Usually no planned downtime; transient erythema, edema, tenderness, bruising, welts, or altered sensation can occur.","swelling_text":"Mild transient edema is reported.","bruising_text":"Possible but not universal.","exercise_restrictions":null,"longevity_text":"Published reviews report improvement assessed out to roughly one year, while manufacturer materials say a year or longer; durability varies.","pain_level":"Published systematic reviews describe moderate treatment discomfort on average, with substantial patient and protocol variation.","reversibility":"Not reversible; deposited thermal-coagulation points cannot be removed.","major_risks":"Pain, redness, swelling, bruising, welts, transient numbness or weakness, burns, scarring, and contour change; correct depth and anatomy are critical.","most_likely_disappointment":"The measured lift is generally modest and may not be visible enough for someone seeking surgical-level change.","marketing_misconception":"Treatment at a deep support layer is not equivalent to surgically repositioning that layer.","provider_variables":"Imaging, line count, transducer depth, vector planning, energy, tissue coupling, anatomy, and pain management.","skin_tone_notes":"Ultrasound is not melanin-targeted, but injury, burns, and post-inflammatory pigment change can still follow poor technique.","pricing_basis":"Usually per treatment area and number of lines; full-face, lower-face/neck, brow, and chest quotes should remain separate.","expected_result_magnitude":"Modest noninvasive lift in appropriately selected mild-to-moderate laxity.","true_substitute_notes":"Overlaps with Thermage in broad goals but uses focused ultrasound rather than monopolar RF and has different depth, discomfort, and planning variables.","when_not_appropriate":"Not appropriate for surgical-level laxity expectations or where IFU contraindications, open wounds, severe acne, or implanted devices in the treatment path apply.","fda_status":"FDA 510(k)-cleared through device-specific submissions including K121700 for brow, submental, and neck lifting and K134032 for décolletage lines.","canada_status":"Health Canada MDALL lists the Ulthera System under active Class III licence 79689.","evidence_grade":"High for device identity and cleared indications; moderate for modest efficacy and one-year durability, with heterogeneous protocols.","at_a_glance":{"onset":"Gradual over 2–6 months","duration":"Evidence commonly follows results to about 1 year","downtime":"Usually none planned; tenderness/swelling possible","discomfort":"Moderate on average in reviews","reversibility":"Not reversible"},"sort_rank":420,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"Morpheus8","slug":"morpheus8","entity_type":"device","parent_slug":"energy-device","manufacturer":"InMode","category":"Energy device","treatment_class":"Fractional radiofrequency microneedling","generic_name":"fractional bipolar radiofrequency microneedling system","brand_name":"Morpheus8","summary":"A fractional radiofrequency device that inserts an array of electrodes into tissue and delivers RF energy at selected depths.","primary_purpose":"Dermatologic and surgical procedures requiring electrocoagulation, hemostasis, or contraction/coagulation of soft tissue within the device's cleared parameters.","mechanism":"Programmable needle electrodes penetrate tissue and deliver fractional bipolar radiofrequency, creating discrete zones of thermal coagulation at selected depths.","intended_areas":["face","neck","body","acne scars"],"what_it_changes":"May remodel texture, scars, and laxity through combined needle injury and thermal coagulation; exact use depends on tip and settings.","what_it_does_not_change":"It does not add filler volume and its 510(k) clearance does not establish superiority over other RF-microneedling devices.","adds_volume":"No","tightening_level":"Potentially modest to moderate, highly protocol and patient dependent.","result_timing":"Early treatment effects evolve over weeks to months as healing and remodelling occur.","sessions_text":"Often delivered as a series, but a universal session count is not established by the FDA clearance; protocol depends on indication and settings.","appointment_time":null,"downtime_text":"Redness, swelling, crusting, pinpoint bleeding, tenderness, and temporary track marks can occur; deeper or higher-energy treatment can extend recovery.","swelling_text":"Common after treatment.","bruising_text":"Possible from needle penetration.","exercise_restrictions":null,"longevity_text":null,"pain_level":null,"reversibility":"Not reversible; needle and thermal injury cannot be withdrawn.","major_risks":"Pain, bleeding, infection, burns, pigment change, scarring, fat loss, contour change, nerve injury, and disfigurement. FDA issued a 2025 safety communication about serious complications reported with certain RF-microneedling uses.","most_likely_disappointment":"Device branding can obscure how strongly depth, energy, passes, tip, and provider judgment determine both result and risk.","marketing_misconception":"FDA clearance for coagulation/contraction uses is not a blanket clearance for every advertised wrinkle, scar, fat-remodelling, or tightening claim.","provider_variables":"Needle depth, coated versus uncoated tip, energy per pin, pulse duration, passes, overlap, treatment endpoint, anatomy, anesthesia, and infection control.","skin_tone_notes":"The K231790 clearance limits energy above 62 mJ per pin to Fitzpatrick skin types I–IV. Lower-energy treatment still requires individualized settings and pigment-risk counselling.","pricing_basis":"Usually per session and treatment area; package prices must be normalized to a per-session equivalent without mixing promotions.","expected_result_magnitude":"Variable; depends more on protocol and indication than on device name alone.","true_substitute_notes":"Morpheus8 and Potenza share an RF-microneedling category but differ in cleared language, tips, energy delivery, and protocols.","when_not_appropriate":"When the patient cannot accept thermal-injury risks, has active infection or impaired healing, or expects a result outside the supported device indication.","fda_status":"FDA 510(k)-cleared, including K231790, for specified dermatologic and surgical electrocoagulation, hemostasis, and soft-tissue coagulation/contraction uses; high-energy use has a Fitzpatrick-type limitation.","canada_status":"Health Canada MDALL lists active Class III InMode fractional RF device licences that include Morpheus8 configurations; exact model and handpiece should be verified.","evidence_grade":"High for device mechanism, clearance boundaries, and current FDA safety warning; lower and heterogeneous for aesthetic protocol, session count, and durability.","at_a_glance":{"onset":"Evolves over weeks to months","duration":"Not responsibly standardized","downtime":"Redness/swelling and surface reaction for days","reversibility":"Not reversible"},"sort_rank":430,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"Potenza","slug":"potenza","entity_type":"device","parent_slug":"energy-device","manufacturer":"Cynosure / Jeisys Medical","category":"Energy device","treatment_class":"Fractional radiofrequency microneedling","generic_name":"radiofrequency microneedle electrosurgical unit","brand_name":"Potenza","summary":"A radiofrequency microneedling platform with multiple monopolar/bipolar and insulated/non-insulated tip configurations.","primary_purpose":"Dermatologic and general surgical procedures for electrocoagulation and hemostasis under the US clearance; advertised cosmetic protocols go beyond that narrow cleared wording.","mechanism":"Microneedle electrodes enter tissue and deliver monopolar or bipolar radiofrequency through selected insulated or non-insulated tip configurations, producing controlled coagulation.","intended_areas":["face","neck","body","scars"],"what_it_changes":"Can create fractional needle and thermal injury used in clinician-directed resurfacing or remodelling protocols.","what_it_does_not_change":"It does not add volume, and the US clearance does not itself establish a wrinkle, acne-scar, or tightening indication.","adds_volume":"No","tightening_level":"Potentially modest to moderate in aesthetic protocols, but not established as a specific FDA-cleared outcome.","result_timing":"Remodelling, if achieved, develops over weeks to months rather than immediately.","sessions_text":"Often used in a series, but no universal session count is established by the US clearance.","appointment_time":null,"downtime_text":"Redness, swelling, tenderness, pinpoint bleeding, crusting, and temporary needle marks can occur.","swelling_text":"Common after treatment.","bruising_text":"Possible from needle penetration.","exercise_restrictions":null,"longevity_text":null,"pain_level":null,"reversibility":"Not reversible; thermal and needle injury cannot be withdrawn.","major_risks":"Pain, bleeding, infection, burns, scarring, pigment change, fat loss, contour change, and nerve injury; the FDA's 2025 RF-microneedling safety communication applies to the procedure category.","most_likely_disappointment":"Many public claims describe cosmetic outcomes that are not the same as the device's narrow US cleared indication.","marketing_misconception":"The number of modes or tips does not by itself prove superior results or safety.","provider_variables":"Tip selection, insulated status, monopolar or bipolar mode, depth, energy, pulse duration, passes, overlap, anesthesia, and infection control.","skin_tone_notes":"RF is not melanin-targeted, but burns and post-inflammatory pigment change remain possible; no equivalence across all skin tones is inferred from clearance.","pricing_basis":"Usually per session and treatment area; packages should be converted only when the included area and session count are explicit.","expected_result_magnitude":"Variable and protocol dependent.","true_substitute_notes":"Same broad device category as Morpheus8, but different hardware, tips, cleared wording, and protocol choices prevent simple equivalence.","when_not_appropriate":"When active infection, impaired healing, implanted-device concerns, or unwillingness to accept thermal injury makes treatment unsuitable; exact IFU screening is required.","fda_status":"FDA 510(k)-cleared under K192545 for dermatologic and general surgical procedures for electrocoagulation and hemostasis. The clearance should not be rewritten as an FDA-cleared wrinkle or skin-tightening indication.","canada_status":"Health Canada MDALL lists Potenza Fractional RF Microneedle Electrosurgical Unit under active Class III licence 106699.","evidence_grade":"High for device identity, mechanism, and regulatory boundaries; limited for product-specific comparative efficacy, session count, and durability.","at_a_glance":{"onset":"Evolves over weeks to months","duration":"Not responsibly standardized","downtime":"Redness/swelling and surface reaction for days","reversibility":"Not reversible"},"sort_rank":440,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"HydraFacial","slug":"hydrafacial","entity_type":"procedure","parent_slug":null,"manufacturer":"The Beauty Health Company","category":"Facial","treatment_class":"Powered hydradermabrasion facial","generic_name":"powered dermabrasion with suction and fluid delivery","brand_name":"HydraFacial","summary":"A branded superficial facial procedure combining powered exfoliation, suction-based extraction, and topical solution delivery.","primary_purpose":"Temporary improvement in surface cleansing, exfoliation, hydration, and cosmetic appearance.","mechanism":"A handheld tip uses controlled suction and fluid flow to exfoliate the stratum corneum, remove surface debris, and deliver topical solutions.","intended_areas":["face","neck","décolletage","back"],"what_it_changes":"Surface debris, temporary hydration, smoothness, and visible radiance.","what_it_does_not_change":"It does not add structural volume, relax muscles, tighten deep tissue, or produce surgical or injectable-level contour change.","adds_volume":"No","tightening_level":"None","result_timing":"Surface smoothness and hydration are typically assessed immediately after treatment.","sessions_text":"One session for a temporary surface effect; repeat or maintenance frequency is elective and not a durable regulatory claim.","appointment_time":"Common branded protocols are approximately 30 minutes, with longer deluxe protocols possible.","downtime_text":"Usually no planned downtime, though transient redness, sensitivity, irritation, or breakout can occur.","swelling_text":"Not expected as a routine effect; stop and assess unexpected swelling.","bruising_text":"Not expected with routine settings, but excessive suction can mark fragile skin.","exercise_restrictions":null,"longevity_text":null,"pain_level":null,"reversibility":"The superficial exfoliation is not reversible, but the cosmetic hydration effect is temporary.","major_risks":"Irritation, redness, sensitivity, abrasion, suction marks, infection if hygiene is inadequate, and reaction to topical solutions; device and solution contraindications must be screened.","most_likely_disappointment":"The immediate glow is superficial and temporary and will not correct laxity, muscle-driven lines, scars, or volume loss.","marketing_misconception":"Infusing topical serum during a facial is not equivalent to injecting filler or delivering a deep tightening treatment.","provider_variables":"Tip, suction level, number of passes, solution choice, skin-barrier assessment, hygiene, and whether add-ons change the procedure.","skin_tone_notes":"Avoid overly aggressive suction or exfoliation in anyone prone to post-inflammatory pigment change; no universal skin-tone outcome is inferred.","pricing_basis":"Per session and protocol tier; Signature, Deluxe, Platinum, boosters, and packages must remain distinct.","expected_result_magnitude":"Temporary superficial cosmetic improvement.","true_substitute_notes":"Broadly comparable with DiamondGlow for a surface facial goal, but the handpieces, exfoliation method, and topical-delivery systems differ.","when_not_appropriate":"When the skin barrier is compromised, there is active infection or inflammatory disease, a solution allergy is present, or the goal requires deeper medical correction.","fda_status":"No HydraFacial-branded PMA, De Novo, or 510(k) indication was identified in this review; do not describe the cosmetic facial itself as FDA approved. Device model registration and exemption status are model-specific.","canada_status":"Health Canada MDALL lists HydraFacial microdermabrasion systems under active Class II licence 79154 and a handpiece licence 79395; exact model and intended use should be verified.","evidence_grade":"Moderate for device process and short-term surface effects; limited for durable clinical outcomes and no longevity claim is published.","at_a_glance":{"onset":"Immediate surface effect","duration":"Not durably established","downtime":"Usually none planned","reversibility":"Temporary cosmetic effect"},"sort_rank":510,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"},{"name":"DiamondGlow","slug":"diamondglow","entity_type":"procedure","parent_slug":null,"manufacturer":"Allergan Aesthetics / Envy Medical","category":"Facial","treatment_class":"Diamond-tip dermabrasion with suction and topical infusion","generic_name":"powered dermabrasion with simultaneous suction and topical delivery","brand_name":"DiamondGlow","summary":"A branded superficial facial procedure using a reusable diamond tip, suction, and simultaneous delivery of topical Pro-Infusion solutions.","primary_purpose":"Temporary surface exfoliation, extraction, and topical infusion for smoother, brighter-looking skin.","mechanism":"A diamond-tip handpiece abrades the superficial stratum corneum while suction removes debris and the device delivers a selected topical solution.","intended_areas":["face","neck","décolletage","body"],"what_it_changes":"Superficial texture, debris, and temporary hydrated appearance.","what_it_does_not_change":"It does not add structural volume, relax muscle activity, tighten deep tissue, or replace scar resurfacing.","adds_volume":"No","tightening_level":"None","result_timing":"Surface cosmetic change is assessed immediately after treatment.","sessions_text":"One session for temporary surface improvement; repeat treatments are elective and durability is not established here.","appointment_time":"The manufacturer describes a treatment of approximately 30 minutes.","downtime_text":"Usually no planned downtime, although redness, sensitivity, abrasion, suction marks, or reaction to topical products can occur.","swelling_text":"Not expected routinely; unexpected swelling warrants assessment.","bruising_text":"Not expected routinely, but excessive suction can mark fragile skin.","exercise_restrictions":null,"longevity_text":null,"pain_level":null,"reversibility":"Superficial exfoliation is not reversible; the cosmetic hydration effect is temporary.","major_risks":"Irritation, erythema, abrasion, suction marks, infection if hygiene is inadequate, and reactions to topical solutions; contraindications in the user manual must be followed.","most_likely_disappointment":"A polished immediate appearance is temporary and does not correct deep wrinkles, laxity, muscle pull, or volume loss.","marketing_misconception":"Topical infusion during dermabrasion is not injectable delivery into deep tissue.","provider_variables":"Diamond-tip grit, suction, passes, pressure, solution choice, hygiene, and skin-barrier assessment.","skin_tone_notes":"Aggressive abrasion can provoke post-inflammatory pigment change in susceptible skin; conservative technique and barrier assessment matter.","pricing_basis":"Per session and protocol; full-face, body, add-on, package, promotion, and membership prices must remain separate.","expected_result_magnitude":"Temporary superficial cosmetic improvement.","true_substitute_notes":"Broadly comparable with HydraFacial for a superficial facial goal, but uses diamond-tip abrasion rather than HydraFacial's proprietary vortex-style tip and fluid path.","when_not_appropriate":"When there is active infection, open or compromised skin, significant inflammatory disease, solution allergy, or a goal requiring deeper treatment.","fda_status":"The underlying SilkPeel/Dermalinfusion powered-dermabrasion device family is FDA-listed as Class I under product code GFE and described in FDA records as 510(k)-exempt; this is not FDA approval of every DiamondGlow cosmetic claim.","canada_status":"No DiamondGlow-named Class II–IV active MDALL licence was identified. Class I devices do not receive an MDALL device licence, so Canadian establishment and model status require separate verification.","evidence_grade":"Moderate for device process and immediate surface effects; limited for durable outcomes, and no longevity claim is published.","at_a_glance":{"onset":"Immediate surface effect","duration":"Not durably established","downtime":"Usually none planned","reversibility":"Temporary cosmetic effect"},"sort_rank":520,"publication_status":"published","is_sample":false,"last_reviewed_at":"2026-07-29"}]$treatments$::jsonb) as p(
