  name = excluded.name,
  entity_type = excluded.entity_type,
  manufacturer = excluded.manufacturer,
  category = excluded.category,
  treatment_class = excluded.treatment_class,
  generic_name = excluded.generic_name,
  brand_name = excluded.brand_name,
  summary = excluded.summary,
  primary_purpose = excluded.primary_purpose,
  mechanism = excluded.mechanism,
  intended_areas = excluded.intended_areas,
  what_it_changes = excluded.what_it_changes,
  what_it_does_not_change = excluded.what_it_does_not_change,
  adds_volume = excluded.adds_volume,
  tightening_level = excluded.tightening_level,
  result_timing = excluded.result_timing,
  sessions_text = excluded.sessions_text,
  appointment_time = excluded.appointment_time,
  downtime_text = excluded.downtime_text,
  swelling_text = excluded.swelling_text,
  bruising_text = excluded.bruising_text,
  exercise_restrictions = excluded.exercise_restrictions,
  longevity_text = excluded.longevity_text,
  pain_level = excluded.pain_level,
  reversibility = excluded.reversibility,
  major_risks = excluded.major_risks,
  most_likely_disappointment = excluded.most_likely_disappointment,
  marketing_misconception = excluded.marketing_misconception,
  provider_variables = excluded.provider_variables,
  skin_tone_notes = excluded.skin_tone_notes,
  pricing_basis = excluded.pricing_basis,
  expected_result_magnitude = excluded.expected_result_magnitude,
  true_substitute_notes = excluded.true_substitute_notes,
  when_not_appropriate = excluded.when_not_appropriate,
  fda_status = excluded.fda_status,
  canada_status = excluded.canada_status,
  evidence_grade = excluded.evidence_grade,
  at_a_glance = excluded.at_a_glance,
  sort_rank = excluded.sort_rank,
  publication_status = excluded.publication_status,
  is_sample = excluded.is_sample,
  last_reviewed_at = excluded.last_reviewed_at,
  updated_at = now();

-- Resolve parents only after every launch entity exists.
with payload as (
  select *
  from jsonb_to_recordset($parents$[{"slug":"botox","parent_slug":"neuromodulator"},{"slug":"dysport","parent_slug":"neuromodulator"},{"slug":"ha-filler","parent_slug":null},{"slug":"juvederm","parent_slug":"ha-filler"},{"slug":"restylane","parent_slug":"ha-filler"},{"slug":"juvederm-voluma","parent_slug":"juvederm"},{"slug":"restylane-kysse","parent_slug":"restylane"},{"slug":"sculptra","parent_slug":"collagen-stimulator"},{"slug":"radiesse","parent_slug":"collagen-stimulator"},{"slug":"thermage","parent_slug":"energy-device"},{"slug":"ultherapy","parent_slug":"energy-device"},{"slug":"morpheus8","parent_slug":"energy-device"},{"slug":"potenza","parent_slug":"energy-device"},{"slug":"hydrafacial","parent_slug":null},{"slug":"diamondglow","parent_slug":null}]$parents$::jsonb) as p(slug text, parent_slug text)
)
update public.treatments child
set
  parent_id = parent.id,
  updated_at = now()
from payload
left join public.treatments parent on parent.slug = payload.parent_slug
where child.slug = payload.slug
  and child.parent_id is distinct from parent.id;

