update public.treatment_sources source
set
  source_title = payload.source_title,
  source_type = payload.source_type,
  publication_date = payload.publication_date,
  retrieved_at = '2026-07-29T00:00:00Z'::timestamptz,
  evidence_level = payload.evidence_level,
  notes = payload.notes,
  is_sample = false
from payload
join public.treatments treatment on treatment.slug = payload.treatment_slug
where source.treatment_id = treatment.id
  and source.claim_field = payload.claim_field
  and source.source_url = payload.source_url;

