n?companyId=132079&lang=eng","source_type":"Health Canada MDALL","publication_date":null,"evidence_level":"regulatory-primary","notes":"Active Class III licence 106699."},{"treatment_slug":"hydrafacial","claim_field":"primary_purpose","source_title":"HydraFacial Treatment","source_url":"https://hydrafacial.com/treatment/","source_type":"official manufacturer information","publication_date":null,"evidence_level":"manufacturer-primary","notes":"Branded cleanse, extract, and hydrate protocol."},{"treatment_slug":"hydrafacial","claim_field":"mechanism","source_title":"HydraFacial Electronic Instructions for Use","source_url":"https://www.hydrafacial.com/pages/electronic-instructions-for-use-eifu","source_type":"official manufacturer IFU hub","publication_date":null,"evidence_level":"manufacturer-primary","notes":"Device manuals, suction/fluid path, solutions, contraindications, and cleaning."},{"treatment_slug":"hydrafacial","claim_field":"appointment_time","source_title":"HydraFacial Treatment","source_url":"https://hydrafacial.com/treatment/","source_type":"official manufacturer information","publication_date":null,"evidence_level":"manufacturer-primary","notes":"Common 30-minute branded treatment framing."},{"treatment_slug":"hydrafacial","claim_field":"major_risks","source_title":"HydraFacial Electronic Instructions for Use","source_url":"https://www.hydrafacial.com/pages/electronic-instructions-for-use-eifu","source_type":"official manufacturer IFU hub","publication_date":null,"evidence_level":"manufacturer-primary","notes":"Model-specific warnings, contraindications, hygiene, and solution precautions."},{"treatment_slug":"hydrafacial","claim_field":"fda_status","source_title":"FDA 510(k) Premarket Notification Database","source_url":"https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/pmn.cfm","source_type":"FDA device database","publication_date":null,"evidence_level":"regulatory-primary","notes":"Database searched by brand, manufacturer, and model; no HydraFacial-branded PMA, De Novo, or 510(k) indication identified in this review."},{"treatment_slug":"hydrafacial","claim_field":"canada_status","source_title":"Health Canada MDALL: HydraFacial licences","source_url":"https://health-products.canada.ca/mdall-limh/information?companyId=120660&lang=eng","source_type":"Health Canada MDALL","publication_date":null,"evidence_level":"regulatory-primary","notes":"Active Class II microdermabrasion-system licence 79154 and handpiece licence 79395."},{"treatment_slug":"diamondglow","claim_field":"primary_purpose","source_title":"DiamondGlow: How It Works","source_url":"https://www.diamondglow.com/how-it-works/","source_type":"official manufacturer information","publication_date":null,"evidence_level":"manufacturer-primary","notes":"Diamond-tip exfoliation, extraction, and topical infusion process."},{"treatment_slug":"diamondglow","claim_field":"mechanism","source_title":"DiamondGlow: How It Works","source_url":"https://www.diamondglow.com/how-it-works/","source_type":"official manufacturer information","publication_date":null,"evidence_level":"manufacturer-primary","notes":"Simultaneous abrasion, suction, and Pro-Infusion delivery."},{"treatment_slug":"diamondglow","claim_field":"appointment_time","source_title":"DiamondGlow Frequently Asked Questions","source_url":"https://www.diamondglow.com/faq/","source_type":"official manufacturer information","publication_date":null,"evidence_level":"manufacturer-primary","notes":"Approximately 30-minute treatment and user-manual references."},{"treatment_slug":"diamondglow","claim_field":"major_risks","source_title":"DiamondGlow Frequently Asked Questions and Safety Information","source_url":"https://www.diamondglow.com/faq/","source_type":"official manufacturer safety information","publication_date":null,"evidence_level":"manufacturer-primary","notes":"Patient selection and user-manual safety framing."},{"treatment_slug":"diamondglow","claim_field":"fda_status","source_title":"FDA Establishment Registration and Device Listing: Envy Medical powered dermabrasion devices","source_url":"https://www.accessdata.fda.gov/scrIpts/cdrh/cfdocs/cfRL/rl.cfm?lid=964029&lpcd=GFE","source_type":"FDA device listing","publication_date":null,"evidence_level":"regulatory-primary","notes":"Class I product code GFE listing for DPRO, Dermalinfusion, SilkPeel, and related models."},{"treatment_slug":"diamondglow","claim_field":"fda_status","source_title":"FDA MAUDE report identifying SilkPeel Pro Dermalinfusion as 510(k)-exempt","source_url":"https://www.accessdata.fda.gov/scripts/cdrh/cfmaude/detail.cfm?mdrfoi__id=9919070&pc=GFE","source_type":"FDA device adverse-event record","publication_date":"2020-05-05","evidence_level":"regulatory-primary","notes":"Corroborates Class I/510(k)-exempt regulatory pathway; not used to estimate event incidence."},{"treatment_slug":"diamondglow","claim_field":"canada_status","source_title":"Health Canada Medical Devices Active Licence Listing","source_url":"https://www.canada.ca/en/health-canada/services/drugs-health-products/medical-devices/licences/medical-devices-active-licence-listing.html","source_type":"Health Canada regulatory guidance","publication_date":null,"evidence_level":"regulatory-primary","notes":"MDALL covers active Class II–IV device licences; Class I devices do not receive a device licence."}]$sources$::jsonb) as p(
    treatment_slug text,
    claim_field text,
    source_title text,
    source_url text,
    source_type text,
    publication_date date,
    evidence_level text,
    notes text
  )
)
insert into public.treatment_sources (
  treatment_id,
  claim_field,
  source_title,
  source_url,
  source_type,
  publication_date,
  retrieved_at,
  evidence_level,
  notes,
  is_sample
)
select
  treatment.id,
  payload.claim_field,
  payload.source_title,
  payload.source_url,
  payload.source_type,
  payload.publication_date,
  '2026-07-29T00:00:00Z'::timestamptz,
  payload.evidence_level,
  payload.notes,
  false
from payload
join public.treatments treatment on treatment.slug = payload.treatment_slug
where not exists (
  select 1
  from public.treatment_sources source
  where source.treatment_id = treatment.id
    and source.claim_field = payload.claim_field
    and source.source_url = payload.source_url
);

with ranked as (
  select
    source.id,
    row_number() over (
      partition by source.treatment_id, source.claim_field, source.source_url
      order by source.created_at, source.id
    ) as duplicate_rank
  from public.treatment_sources source
  join public.treatments treatment on treatment.id = source.treatment_id
  where treatment.slug = any(array['botox','dysport','ha-filler','juvederm','restylane','juvederm-voluma','restylane-kysse','sculptra','radiesse','thermage','ultherapy','morpheus8','potenza','hydrafacial','diamondglow'])
)
delete from public.treatment_sources source
using ranked
where source.id = ranked.id
  and ranked.duplicate_rank > 1;

-- A launch entity may remain public only when the critical fields and source
-- claims used by the public comparison gate are present.
update public.treatments treatment
set
  publication_status = 'review',
  updated_at = now()
where treatment.slug = any(array['botox','dysport','ha-filler','juvederm','restylane','juvederm-voluma','restylane-kysse','sculptra','radiesse','thermage','ultherapy','morpheus8','potenza','hydrafacial','diamondglow'])
  and (
    treatment.primary_purpose is null
    or treatment.mechanism is null
    or treatment.major_risks is null
    or treatment.fda_status is null
    or treatment.canada_status is null
    or treatment.evidence_grade is null
    or treatment.last_reviewed_at is null
    or exists (
      select 1
      from (values
        ('primary_purpose'),
        ('mechanism'),
        ('major_risks'),
        ('fda_status'),
        ('canada_status')
      ) required(claim_field)
      where not exists (
        select 1
        from public.treatment_sources source
        where source.treatment_id = treatment.id
          and source.claim_field = required.claim_field
          and source.is_sample = false
      )
    )
  );

with payload as (
  select *
  from jsonb_to_recordset($groups$[{"slug":"neuromodulator","name":"Neuromodulators","description":"Botulinum toxin products used to reduce selected muscle activity."},{"slug":"dermal-filler","name":"Dermal fillers","description":"Broad filler class and product records that add or restore volume."},{"slug":"ha-filler-brand-family","name":"HA filler brand families","description":"Manufacturer portfolios of hyaluronic acid filler products."},{"slug":"ha-filler-product","name":"HA filler products","description":"Specific hyaluronic acid filler formulations."},{"slug":"collagen-biostimulator","name":"Collagen biostimulators","description":"Injectables with a clinically relevant tissue-stimulation component."},{"slug":"noninvasive-lifting-device","name":"Non-invasive lifting devices","description":"Noninvasive energy devices used for modest lifting or tightening goals."},{"slug":"rf-microneedling-device","name":"RF microneedling devices","description":"Devices combining needle penetration with radiofrequency coagulation."},{"slug":"resurfacing-device","name":"Resurfacing devices","description":"Reserved for future direct comparisons of energy-based resurfacing devices."},{"slug":"hydradermabrasion-procedure","name":"Hydradermabrasion procedures","description":"Branded superficial facial procedures combining exfoliation, suction, and topical delivery."}]$groups$::jsonb)
    as p(slug text, name text, description text)
)
insert into public.comparison_groups (slug, name)
select slug, name
from payload
on conflict (slug) do update set name = excluded.name;

with payload as (
  select *
  from jsonb_to_recordset($group_mappings$[{"treatment_slug":"neuromodulator","group_slug":"neuromodulator"},{"treatment_slug":"botox","group_slug":"neuromodulator"},{"treatment_slug":"dysport","group_slug":"neuromodulator"},{"treatment_slug":"xeomin","group_slug":"neuromodulator"},{"treatment_slug":"daxxify","group_slug":"neuromodulator"},{"treatment_slug":"ha-filler","group_slug":"dermal-filler"},{"treatment_slug":"juvederm","group_slug":"dermal-filler"},{"treatment_slug":"restylane","group_slug":"dermal-filler"},{"treatment_slug":"juvederm-voluma","group_slug":"dermal-filler"},{"treatment_slug":"restylane-kysse","group_slug":"dermal-filler"},{"treatment_slug":"restylane-lyft","group_slug":"dermal-filler"},{"treatment_slug":"juvederm","group_slug":"ha-filler-brand-family"},{"treatment_slug":"restylane","group_slug":"ha-filler-brand-family"},{"treatment_slug":"juvederm-voluma","group_slug":"ha-filler-product"},{"treatment_slug":"restylane-kysse","group_slug":"ha-filler-product"},{"treatment_slug":"restylane-lyft","group_slug":"ha-filler-product"},{"treatment_slug":"sculptra","group_slug":"collagen-biostimulator"},{"treatment_slug":"radiesse","group_slug":"collagen-biostimulator"},{"treatment_slug":"thermage","group_slug":"noninvasive-lifting-device"},{"treatment_slug":"ultherapy","group_slug":"noninvasive-lifting-device"},{"treatment_slug":"morpheus8","group_slug":"rf-microneedling-device"},{"treatment_slug":"potenza","group_slug":"rf-microneedling-device"},{"treatment_slug":"hydrafacial","group_slug":"hydradermabrasion-procedure"},{"treatment_slug":"diamondglow","group_slug":"hydradermabrasion-procedure"}]$group_mappings$::jsonb)
    as p(treatment_slug text, group_slug text)
)
insert into public.treatment_comparison_groups (treatment_id, comparison_group_id)
select treatment.id, comparison_group.id
from payload
join public.treatments treatment on treatment.slug = payload.treatment_slug
join public.comparison_groups comparison_group on comparison_group.slug = payload.group_slug
on conflict do nothing;

with payload as (
  select *
  from jsonb_to_recordset($family_rules$[{"left_group_slug":"dermal-filler","right_group_slug":"neuromodulator","comparison_mode":"different_approach","template_key":"cross_category","public_label":"Beginner comparison","is_active":true,"editorial_rule":"Explain the structural difference through the two treatment profiles. Do not add a recommendation article, winner, dose conversion, or claim that either approach replaces the other."}]$family_rules$::jsonb) as p(
    left_group_slug text,
    right_group_slug text,
    comparison_mode public.comparison_mode,
    template_key text,
    public_label text,
    is_active boolean,
    editorial_rule text
  )
)
insert into public.comparison_family_rules (
  left_group_slug,
  right_group_slug,
  comparison_mode,
  template_key,
  public_label,
  is_active
)
select
  left_group_slug,
  right_group_slug,
  comparison_mode,
  template_key,
  public_label,
  is_active
from payload
on conflict (left_group_slug, right_group_slug) do update set
  comparison_mode = excluded.comparison_mode,
  template_key = excluded.template_key,
  public_label = excluded.public_label,
  is_active = excluded.is_active,
  updated_at = now();

with payload as (
  select *
  from jsonb_to_recordset($treatment_markets$[{"treatment_slug":"botox","country_code":"US"},{"treatment_slug":"botox","country_code":"CA"},{"treatment_slug":"dysport","country_code":"US"},{"treatment_slug":"dysport","country_code":"CA"},{"treatment_slug":"ha-filler","country_code":"US"},{"treatment_slug":"ha-filler","country_code":"CA"},{"treatment_slug":"juvederm","country_code":"US"},{"treatment_slug":"juvederm","country_code":"CA"},{"treatment_slug":"restylane","country_code":"US"},{"treatment_slug":"restylane","country_code":"CA"},{"treatment_slug":"juvederm-voluma","country_code":"US"},{"treatment_slug":"juvederm-voluma","country_code":"CA"},{"treatment_slug":"restylane-kysse","country_code":"US"},{"treatment_slug":"restylane-kysse","country_code":"CA"},{"treatment_slug":"sculptra","country_code":"US"},{"treatment_slug":"sculptra","country_code":"CA"},{"treatment_slug":"radiesse","country_code":"US"},{"treatment_slug":"radiesse","country_code":"CA"},{"treatment_slug":"thermage","country_code":"US"},{"treatment_slug":"thermage","country_code":"CA"},{"treatment_slug":"ultherapy","country_code":"US"},{"treatment_slug":"ultherapy","country_code":"CA"},{"treatment_slug":"morpheus8","country_code":"US"},{"treatment_slug":"morpheus8","country_code":"CA"},{"treatment_slug":"potenza","country_code":"US"},{"treatment_slug":"potenza","country_code":"CA"},{"treatment_slug":"hydrafacial","country_code":"US"},{"treatment_slug":"hydrafacial","country_code":"CA"},{"treatment_slug":"diamondglow","country_code":"US"},{"treatment_slug":"diamondglow","country_code":"CA"}]$treatment_markets$::jsonb)
    as p(treatment_slug text, country_code text)
)
insert into public.treatment_markets (treatment_id, country_code)
select treatment.id, payload.country_code
from payload
join public.treatments treatment on treatment.slug = payload.treatment_slug
on conflict do nothing;

-- Pair metadata only. The matrix content comes from sourced treatment fields.
with payload as (
  select *
  from jsonb_to_recordset($comparisons$[{"slug":"botox-vs-dysport","treatment_a_slug":"botox","treatment_b_slug":"dysport","comparison_mode":"direct","row_template":"neuromodulator_brands","title_override":"Botox vs. Dysport","description_override":"Compare two botulinum toxin type A products without converting their non-interchangeable potency units.","is_featured":true,"is_indexable":true,"sort_rank":10,"publication_status":"published"},{"slug":"botox-vs-dermal-fillers","treatment_a_slug":"botox","treatment_b_slug":"ha-filler","comparison_mode":"different_approach","row_template":"cross_category","title_override":"Botox vs. dermal fillers","description_override":"A beginner comparison of muscle relaxation and structural volume, explained through profile fields.","is_featured":true,"is_indexable":true,"sort_rank":20,"publication_status":"published","editorial_recommendation_fields":null},{"slug":"juvederm-vs-restylane","treatment_a_slug":"juvederm","treatment_b_slug":"restylane","comparison_mode":"direct","row_template":"filler_families","title_override":"Juvéderm vs. Restylane","description_override":"Compare two HA filler portfolios while keeping product-specific indications visible.","is_featured":true,"is_indexable":true,"sort_rank":30,"publication_status":"published"},{"slug":"juvederm-voluma-vs-restylane-kysse","treatment_a_slug":"juvederm-voluma","treatment_b_slug":"restylane-kysse","comparison_mode":"direct","row_template":"filler_products","title_override":"Juvéderm Voluma vs. Restylane Kysse","description_override":"An intentionally area-mismatched product comparison: structural cheek/chin/temple filler versus lip and upper-perioral filler.","is_featured":true,"is_indexable":true,"sort_rank":40,"publication_status":"published"},{"slug":"sculptra-vs-radiesse","treatment_a_slug":"sculptra","treatment_b_slug":"radiesse","comparison_mode":"direct","row_template":"cross_category","title_override":"Sculptra vs. Radiesse","description_override":"Compare gradual PLLA biostimulation with immediate calcium-hydroxylapatite filler support.","is_featured":true,"is_indexable":true,"sort_rank":50,"publication_status":"published"},{"slug":"thermage-vs-ultherapy","treatment_a_slug":"thermage","treatment_b_slug":"ultherapy","comparison_mode":"direct","row_template":"lifting_devices","title_override":"Thermage FLX vs. Ultherapy","description_override":"Compare monopolar radiofrequency with microfocused ultrasound for modest noninvasive tightening goals.","is_featured":true,"is_indexable":true,"sort_rank":60,"publication_status":"published"},{"slug":"morpheus8-vs-potenza","treatment_a_slug":"morpheus8","treatment_b_slug":"potenza","comparison_mode":"direct","row_template":"resurfacing_devices","title_override":"Morpheus8 vs. Potenza","description_override":"Compare RF-microneedling platforms while preserving their different US clearance wording, tips, and protocol variables.","is_featured":true,"is_indexable":true,"sort_rank":70,"publication_status":"published"},{"slug":"hydrafacial-vs-diamondglow","treatment_a_slug":"hydrafacial","treatment_b_slug":"diamondglow","comparison_mode":"direct","row_template":"resurfacing_devices","title_override":"HydraFacial vs. DiamondGlow","description_override":"Compare two superficial exfoliation, suction, and topical-delivery facials without implying injectable or deep-tightening effects.","is_featured":true,"is_indexable":true,"sort_rank":80,"publication_status":"published"}]$comparisons$::jsonb) as p(
    slug text,
    treatment_a_slug text,
    treatment_b_slug text,
    comparison_mode public.comparison_mode,
    row_template text,
    title_override text,
    description_override text,
    is_featured boolean,
    is_indexable boolean,
    sort_rank integer,
    publication_status public.publication_status,
    editorial_recommendation_fields jsonb
  )
),
resolved as (
  select
    payload.*,
    least(a.id, b.id) as treatment_a_id,
    greatest(a.id, b.id) as treatment_b_id
  from payload
  join public.treatments a on a.slug = payload.treatment_a_slug
  join public.treatments b on b.slug = payload.treatment_b_slug
)
insert into public.comparisons (
  treatment_a_id,
  treatment_b_id,
  slug,
  one_sentence_difference,
  consider_a_when,
  consider_b_when,
  neither_when,
  common_misconception,
  comparison_mode,
  row_template,
  title_override,
  description_override,
  is_featured,
  is_indexable,
  sort_rank,
  publication_status,
  is_sample,
  last_reviewed_at,
  last_verified_at
)
select
  treatment_a_id,
  treatment_b_id,
  slug,
  null,
  null,
  null,
  null,
  null,
  comparison_mode,
  row_template,
  title_override,
  description_override,
  is_featured,
  is_indexable,
  sort_rank,
  publication_status,
  false,
  '2026-07-29T00:00:00Z'::timestamptz,
  '2026-07-29T00:00:00Z'::timestamptz
from resolved
on conflict (pair_key) do update set
  slug = excluded.slug,
  one_sentence_difference = null,
  consider_a_when = null,
  consider_b_when = null,
  neither_when = null,
  common_misconception = null,
  comparison_mode = excluded.comparison_mode,
  row_template = excluded.row_template,
  title_override = excluded.title_override,
  description_override = excluded.description_override,
  is_featured = excluded.is_featured,
  is_indexable = excluded.is_indexable,
  sort_rank = excluded.sort_rank,
  publication_status = excluded.publication_status,
  is_sample = false,
  last_reviewed_at = excluded.last_reviewed_at,
  last_verified_at = excluded.last_verified_at,
  updated_at = now();

-- If either side fell back to review, the comparison cannot be indexed.
update public.comparisons comparison
set
  publication_status = 'review',
  is_indexable = false,
  updated_at = now()
from public.treatments a, public.treatments b
where comparison.slug = any(array['botox-vs-dysport','botox-vs-dermal-fillers','juvederm-vs-restylane','juvederm-voluma-vs-restylane-kysse','sculptra-vs-radiesse','thermage-vs-ultherapy','morpheus8-vs-potenza','hydrafacial-vs-diamondglow'])
  and a.id = comparison.treatment_a_id
  and b.id = comparison.treatment_b_id
  and (
    a.publication_status <> 'published'
    or b.publication_status <> 'published'
    or a.is_sample
    or b.is_sample
  );

with payload as (
  select *
  from jsonb_to_recordset($comparison_markets$[{"comparison_slug":"botox-vs-dysport","country_code":"US","sort_rank":100},{"comparison_slug":"botox-vs-dysport","country_code":"CA","sort_rank":101},{"comparison_slug":"botox-vs-dermal-fillers","country_code":"US","sort_rank":200},{"comparison_slug":"botox-vs-dermal-fillers","country_code":"CA","sort_rank":201},{"comparison_slug":"juvederm-vs-restylane","country_code":"US","sort_rank":300},{"comparison_slug":"juvederm-vs-restylane","country_code":"CA","sort_rank":301},{"comparison_slug":"juvederm-voluma-vs-restylane-kysse","country_code":"US","sort_rank":400},{"comparison_slug":"juvederm-voluma-vs-restylane-kysse","country_code":"CA","sort_rank":401},{"comparison_slug":"sculptra-vs-radiesse","country_code":"US","sort_rank":500},{"comparison_slug":"sculptra-vs-radiesse","country_code":"CA","sort_rank":501},{"comparison_slug":"thermage-vs-ultherapy","country_code":"US","sort_rank":600},{"comparison_slug":"thermage-vs-ultherapy","country_code":"CA","sort_rank":601},{"comparison_slug":"morpheus8-vs-potenza","country_code":"US","sort_rank":700},{"comparison_slug":"morpheus8-vs-potenza","country_code":"CA","sort_rank":701},{"comparison_slug":"hydrafacial-vs-diamondglow","country_code":"US","sort_rank":800},{"comparison_slug":"hydrafacial-vs-diamondglow","country_code":"CA","sort_rank":801}]$comparison_markets$::jsonb)
    as p(comparison_slug text, country_code text, sort_rank integer)
)
insert into public.comparison_markets (comparison_id, country_code, sort_rank)
select comparison.id, payload.country_code, payload.sort_rank
from payload
join public.comparisons comparison on comparison.slug = payload.comparison_slug
on conflict (comparison_id, country_code) do update set sort_rank = excluded.sort_rank;

-- Replace only obsolete launch mappings after the canonical replacement and
-- at least one non-sample source exist. Old group records are retained.
with replacements(old_group_slug, new_group_slug) as (
  values
    ('neuromodulator-brand', 'neuromodulator'),
    ('ha-filler-family', 'ha-filler-brand-family'),
    ('cheek-midface-filler-product', 'ha-filler-product'),
    ('hydradermabrasion-facial', 'hydradermabrasion-procedure')
)
delete from public.treatment_comparison_groups obsolete
using public.treatments treatment, public.comparison_groups old_group, replacements
where obsolete.treatment_id = treatment.id
  and obsolete.comparison_group_id = old_group.id
  and old_group.slug = replacements.old_group_slug
  and treatment.slug = any(array['botox','dysport','ha-filler','juvederm','restylane','juvederm-voluma','restylane-kysse','sculptra','radiesse','thermage','ultherapy','morpheus8','potenza','hydrafacial','diamondglow'])
  and exists (
    select 1
    from public.comparison_groups new_group
    join public.treatment_comparison_groups replacement
      on replacement.comparison_group_id = new_group.id
     and replacement.treatment_id = treatment.id
    where new_group.slug = replacements.new_group_slug
  )
  and exists (
    select 1
    from public.treatment_sources source
    where source.treatment_id = treatment.id
      and source.is_sample = false
  );

