p.vancouverlaser.com/collections/anti-aging-and-needling","https://acdbc.ca/city/vancouver/treatment/skin-tightening-lifting"],"methodology_note":"Used Vancouver Laser's starting price and the current directory's full-face range.","limitations":"Line count, Ultherapy versus Ultherapy Prime, and exact area vary; one source is a marketplace aggregate.","publication_status":"published","researched_at":"2026-07-29","is_sample":false},{"entity_slug":"botox","country":"CA","region_slug":"montreal","region":"Montreal","currency":"CAD","pricing_unit":"per Botox unit","treatment_area":null,"estimated_average":null,"estimated_median":null,"estimated_low":12,"estimated_high":12,"source_count":2,"source_urls":["https://cliniquelacle.com/en","https://idealbodyclinic.com/fr/blog/decouvrez-nos-tarifs-pour-les-injections-esthetiques-a-la-clinique-corps-ideal-montreal/"],"methodology_note":"Compared two regular public per-unit prices.","limitations":"One source says 'from'; consultation and prescriber fees may apply.","publication_status":"published","researched_at":"2026-07-29","is_sample":false},{"entity_slug":"ha-filler","country":"CA","region_slug":"montreal","region":"Montreal","currency":"CAD","pricing_unit":"per syringe","treatment_area":null,"estimated_average":null,"estimated_median":null,"estimated_low":550,"estimated_high":650,"source_count":2,"source_urls":["https://cliniquelacle.com/en","https://idealbodyclinic.com/fr/blog/decouvrez-nos-tarifs-pour-les-injections-esthetiques-a-la-clinique-corps-ideal-montreal/"],"methodology_note":"Compared La Clé's starting price with Ideal Body Clinic's regular Juvéderm and Restylane values.","limitations":"Specific product, syringe volume, treatment area, and consultation fee require confirmation.","publication_status":"published","researched_at":"2026-07-29","is_sample":false},{"entity_slug":"sculptra","country":"CA","region_slug":"montreal","region":"Montreal","currency":"CAD","pricing_unit":"per vial","treatment_area":"face","estimated_average":766.67,"estimated_median":850,"estimated_low":550,"estimated_high":900,"source_count":3,"source_urls":["https://cliniquelacle.com/en","https://cliniqueduo.com/tarifs-et-financement/","https://idealbodyclinic.com/fr/blog/decouvrez-nos-tarifs-pour-les-injections-esthetiques-a-la-clinique-corps-ideal-montreal/"],"methodology_note":"Used regular or starting one-vial public prices; promotional two-vial pricing was excluded.","limitations":"One value is a starting price and total course uses multiple vials.","publication_status":"published","researched_at":"2026-07-29","is_sample":false},{"entity_slug":"morpheus8","country":"CA","region_slug":"montreal","region":"Montreal","currency":"CAD","pricing_unit":"per session","treatment_area":"face","estimated_average":null,"estimated_median":null,"estimated_low":900,"estimated_high":900,"source_count":2,"source_urls":["https://elle.clinic/our-price-list/","https://cliniqueduo.com/tarifs-et-financement/"],"methodology_note":"Compared two regular public face-session prices; trial and package values were excluded.","limitations":"One clinic publishes 'from'; tip, anesthesia, and face-and-neck scope may alter the quote.","publication_status":"published","researched_at":"2026-07-29","is_sample":false},{"entity_slug":"hydrafacial","country":"CA","region_slug":"montreal","region":"Montreal","currency":"CAD","pricing_unit":"per session","treatment_area":"face","estimated_average":298.13,"estimated_median":265,"estimated_low":175,"estimated_high":500,"source_count":4,"source_urls":["https://elle.clinic/our-price-list/","https://cliniqueduo.com/tarifs-et-financement/","https://asamysourcils.com/services/hydrafacial","https://www.fourseasons.com/montreal/spa/hydrafacial/"],"methodology_note":"Used regular public face-session values; the midpoint represented Four Seasons' weekday/weekend Signature Supreme range.","limitations":"Protocols range from short clinic facials to a 75-minute hotel-spa service; promotions and trial prices were excluded.","publication_status":"published","researched_at":"2026-07-29","is_sample":false}]$prices$::jsonb) as p(
    entity_slug text,
    country text,
    region_slug text,
    region text,
    currency text,
    pricing_unit text,
    treatment_area text,
    estimated_average numeric,
    estimated_median numeric,
    estimated_low numeric,
    estimated_high numeric,
    source_count integer,
    source_urls jsonb,
    methodology_note text,
    limitations text,
    researched_at date,
    publication_status public.publication_status,
    is_sample boolean
  )
)
update public.regional_price_estimates estimate
set
  region_name = payload.region,
  currency = payload.currency,
  estimated_average = payload.estimated_average,
  estimated_median = payload.estimated_median,
  estimated_low = payload.estimated_low,
  estimated_high = payload.estimated_high,
  source_count = payload.source_count,
  source_urls = payload.source_urls,
  methodology_note = payload.methodology_note,
  limitations = payload.limitations,
  researched_at = payload.researched_at,
  publication_status = payload.publication_status,
  is_sample = payload.is_sample,
  updated_at = now()
from payload
join public.treatments treatment on treatment.slug = payload.entity_slug
where estimate.treatment_id = treatment.id
  and estimate.comparison_group_slug is null
  and estimate.country_code = payload.country
  and estimate.region_slug = payload.region_slug
  and estimate.pricing_unit = payload.pricing_unit
  and coalesce(estimate.treatment_area, '') = coalesce(payload.treatment_area, '');

with payload as (
  select *
