insert into public.regional_price_estimates (
  treatment_id,
  comparison_group_slug,
  country_code,
  region_slug,
  region_name,
  currency,
  pricing_unit,
  treatment_area,
  estimated_average,
  estimated_median,
  estimated_low,
  estimated_high,
  source_count,
  source_urls,
  methodology_note,
  limitations,
  researched_at,
  publication_status,
  is_sample
)
select
  treatment.id,
  null,
  payload.country,
  payload.region_slug,
  payload.region,
  payload.currency,
  payload.pricing_unit,
  payload.treatment_area,
  payload.estimated_average,
  payload.estimated_median,
  payload.estimated_low,
  payload.estimated_high,
  payload.source_count,
  payload.source_urls,
  payload.methodology_note,
  payload.limitations,
  payload.researched_at,
  payload.publication_status,
  payload.is_sample
from payload
join public.treatments treatment on treatment.slug = payload.entity_slug
where not exists (
  select 1
  from public.regional_price_estimates estimate
  where estimate.treatment_id = treatment.id
    and estimate.comparison_group_slug is null
    and estimate.country_code = payload.country
    and estimate.region_slug = payload.region_slug
    and estimate.pricing_unit = payload.pricing_unit
    and coalesce(estimate.treatment_area, '') = coalesce(payload.treatment_area, '')
);

with ranked as (
  select
    estimate.id,
    row_number() over (
      partition by
        estimate.treatment_id,
        estimate.country_code,
        estimate.region_slug,
        estimate.pricing_unit,
        coalesce(estimate.treatment_area, '')
      order by estimate.created_at, estimate.id
    ) as duplicate_rank
  from public.regional_price_estimates estimate
  join public.treatments treatment on treatment.id = estimate.treatment_id
  where treatment.slug = any(array['botox','dysport','ha-filler','restylane-kysse','sculptra','juvederm-voluma','radiesse','morpheus8','hydrafacial','juvederm','restylane','thermage','ultherapy'])
    and estimate.comparison_group_slug is null
)
delete from public.regional_price_estimates estimate
using ranked
where estimate.id = ranked.id
  and ranked.duplicate_rank > 1;

