insert into public.postal_region_map (
  country_code,
  postal_prefix,
  region_slug,
  city_name
)
select
  country_code,
  postal_prefix,
  region_slug,
  city_name
from payload
on conflict (country_code, postal_prefix) do update set
  region_slug = excluded.region_slug,
  city_name = excluded.city_name,
  updated_at = now();

-- Fail atomically if an expected entity, parent, comparison, or source-backed
-- publication invariant is missing.
do $validation$
declare
  missing_count integer;
begin
  select count(*)
  into missing_count
  from unnest(array['botox','dysport','ha-filler','juvederm','restylane','juvederm-voluma','restylane-kysse','sculptra','radiesse','thermage','ultherapy','morpheus8','potenza','hydrafacial','diamondglow']) as expected(slug)
  where not exists (
    select 1
    from public.treatments treatment
    where treatment.slug = expected.slug
  );
  if missing_count > 0 then
    raise exception 'MVP migration is missing % expected treatment rows', missing_count;
  end if;

  select count(*)
  into missing_count
  from unnest(array['botox','dysport','juvederm','restylane','juvederm-voluma','restylane-kysse','sculptra','radiesse','thermage','ultherapy','morpheus8','potenza']) as expected(slug)
  join public.treatments child on child.slug = expected.slug
  where child.parent_id is null;
  if missing_count > 0 then
    raise exception 'MVP migration could not resolve % treatment parents', missing_count;
  end if;

  select count(*)
  into missing_count
  from unnest(array['botox-vs-dysport','botox-vs-dermal-fillers','juvederm-vs-restylane','juvederm-voluma-vs-restylane-kysse','sculptra-vs-radiesse','thermage-vs-ultherapy','morpheus8-vs-potenza','hydrafacial-vs-diamondglow']) as expected(slug)
  where not exists (
    select 1
    from public.comparisons comparison
    where comparison.slug = expected.slug
  );
  if missing_count > 0 then
    raise exception 'MVP migration is missing % comparison rows', missing_count;
  end if;
end
$validation$;

-- The migration never inserts treatment_media. Existing media remains subject
-- to its rights_verified_at and permitted-licence public-read policy.

commit;
